        var stale=limits.quote(mayor,town,P,new Limits(1000,2000),"stale");policy(2000,2100,()->{denied(()->limits.confirm(mayor,stale),"stale policy revision cannot overwrite newer mayor decision");policy(2000,2000,()->await(debit(H,100),row->in(()->{check(status(H).equals("PREPARED")&&ledger.image().debits().get(H).admission().perDay()==2000,"exact prepared payment retained for full restart");SuiteState.freeze(getName());drainAudit(this::finishPhase);})));});
