        var type=Class.forName("ru.neverland.townycontrol.AuditCategory",true,Bukkit.getPluginManager().getPlugin("NeverLandTownyControl").getClass().getClassLoader());var method=type.getDeclaredMethod("kind",String.class);method.setAccessible(true);check(method.invoke(null,"COUNCIL_SPENDING_LIMIT").equals("Ограничения расходов жителей"),"admin category has readable label for limit changes");
        var lock=writerLock(councilPlugin,rules);lock.lock();CompletionStage<State> accepted;long elapsed;try{accepted=limits.confirm(mayor,limits.quote(mayor,town,P,new Limits(3000,3000),"Shutdown accepted limits"));long start=System.nanoTime();councilPlugin.onDisable();elapsed=System.nanoTime()-start;check(elapsed<200_000_000L&&!accepted.toCompletableFuture().isDone(),"onDisable under external Suite returns without waiting for physical writer");}finally{lock.unlock();}
