        public boolean hasAccount(Account account){return true;}public double getBalance(Account account){return money;}public void newAccount(Account account){}public void deleteAccount(Account account){}public boolean renameAccount(Account account,String name){return true;}public boolean setBalance(Account account,double amount){money=amount;return true;}public String getFormattedBalance(double value){return Double.toString(value);}
